data.server.conf:
{
  "plugins": {
    "DataStore": [
      {
        "sql": {
          "plugin_data": {
            "connection_string": "host=identity-db.database.example.org port=5432 dbname=identity user=identity_server sslmode=verify-full sslrootcert=/run/spire/database-ca/ca.crt sslcert=/run/spire/database/tls.crt sslkey=/run/spire/database/tls.key connect_timeout=5",
            "database_type": "postgres",
            "disable_migration": true,
            "max_idle_conns": 10,
            "max_open_conns": 50
          }
        }
      }
    ],
    "KeyManager": [
      {
        "aws_kms": {
          "plugin_data": {
            "enable_tag_based_key_discovery": true,
            "key_identifier_value": "$SPIRE_SERVER_ID",
            "key_policy_file": "/run/spire/config/kms-key-policy.json",
            "key_tags": {
              "Environment": "production"
            },
            "region": "eu-west-1"
          }
        }
      }
    ],
    "NodeAttestor": [
      {
        "k8s_psat": {
          "plugin_data": {
            "clusters": {
              "production-eu1": {
                "allowed_node_label_keys": [
                  "workload-identity.platform.example.node-restriction.kubernetes.io/pool"
                ],
                "audience": [
                  "spire-server"
                ],
                "service_account_allow_list": [
                  "identity-agents:spire-agent"
                ]
              }
            }
          }
        }
      }
    ]
  },
  "server": {
    "agent_ttl": "3590s",
    "audit_log_enabled": true,
    "bind_address": "0.0.0.0",
    "bind_port": 8081,
    "ca_key_type": "ec-p256",
    "ca_ttl": "24h",
    "data_dir": "/var/lib/spire",
    "default_x509_svid_ttl": "3590s",
    "log_format": "json",
    "log_level": "INFO",
    "socket_path": "/run/spire/admin/api.sock",
    "tls_config": {
      "min_tls_version": "VersionTLS13"
    },
    "trust_domain": "production.identity.example.org"
  }
}
